typedef errno_t = int;
typedef Darterrno_t = int;

enum FFmpegKitSessionState {
  FFMPEG_KIT_SESSION_STATE_CREATED(0),
  FFMPEG_KIT_SESSION_STATE_RUNNING(1),
  FFMPEG_KIT_SESSION_STATE_COMPLETED(2),
  FFMPEG_KIT_SESSION_STATE_FAILED(3);

  final int value;
  const FFmpegKitSessionState(this.value);

  static FFmpegKitSessionState fromValue(int value) => switch (value) {
    0 => FFMPEG_KIT_SESSION_STATE_CREATED,
    1 => FFMPEG_KIT_SESSION_STATE_RUNNING,
    2 => FFMPEG_KIT_SESSION_STATE_COMPLETED,
    3 => FFMPEG_KIT_SESSION_STATE_FAILED,
    _ => throw ArgumentError("Unknown value for FFmpegKitSessionState: $value"),
  };
}

enum FFmpegKitLogLevel {
  FFMPEG_KIT_LOG_LEVEL_STDERR(-16),
  FFMPEG_KIT_LOG_LEVEL_QUIET(-8),
  FFMPEG_KIT_LOG_LEVEL_PANIC(0),
  FFMPEG_KIT_LOG_LEVEL_FATAL(8),
  FFMPEG_KIT_LOG_LEVEL_ERROR(16),
  FFMPEG_KIT_LOG_LEVEL_WARNING(24),
